INSERT INTO `behavioral_indicators` VALUES (1,1,'وقتی اتفاقی برایش می‌افتد، می‌تواند آن را با ترتیب و جزئیات برای دیگران تعریف کند.','positive',NULL,1,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(2,1,'داستان یا خاطره‌ای را که شنیده، می‌تواند با زبان خودش برای دیگران بازگو کند.','positive',NULL,2,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(3,1,'برای توضیح منظور خود، معمولاً از مثال یا توضیح مناسب استفاده می‌کند.','positive',NULL,3,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(4,1,'درباره معنی بعضی کلمات یا تفاوت میان کلمات سؤال می‌پرسد.','positive',NULL,4,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(5,1,'شعر، داستان یا مطالب شنیداری را نسبتاً سریع به خاطر می‌سپارد.','positive',NULL,5,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(6,1,'می‌تواند قوانین یک بازی یا روش انجام یک کار را برای فرد دیگری توضیح دهد.','positive',NULL,6,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(7,1,'هنگام مخالفت با نظر دیگران، تلاش می‌کند منظور خود را با توضیح و دلیل بیان کند.','positive',NULL,7,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(8,1,'هنگام گفت‌وگو معمولاً می‌تواند منظور خود را روشن و قابل‌فهم بیان کند.','positive',NULL,8,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(9,2,'درباره علت اتفاق‌ها سؤال می‌پرسد و می‌خواهد بداند «چرا» چیزی اتفاق افتاده است.','positive',NULL,1,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(10,2,'از معما، مسئله فکری یا بازی‌هایی که نیاز به فکر کردن دارند لذت می‌برد.','positive',NULL,2,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(11,2,'می‌تواند وسایل را بر اساس ویژگی‌هایی مانند اندازه، شکل، رنگ یا کاربرد دسته‌بندی کند.','positive',NULL,3,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(12,2,'الگوها یا نظم‌هایی را که در عددها، شکل‌ها یا اتفاق‌ها وجود دارد، نسبتاً سریع پیدا می‌کند.','positive',NULL,4,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(13,2,'وقتی با مشکلی روبه‌رو می‌شود، برای حل آن فقط به یک راه فکر نمی‌کند و راه‌های دیگری نیز پیشنهاد می‌دهد.','positive',NULL,5,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(14,2,'قوانین بازی‌های فکری یا بازی‌های دارای قانون را نسبتاً سریع متوجه می‌شود.','positive',NULL,6,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(15,2,'قبل از انجام یک کار پیچیده، درباره ترتیب انجام مراحل آن فکر می‌کند.','positive',NULL,7,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(16,2,'اگر در یک مسئله یا استدلال اشتباهی وجود داشته باشد، تلاش می‌کند آن را پیدا کند.','positive',NULL,8,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(17,3,'بدون اینکه کسی مستقیم به او بگوید، معمولاً متوجه ناراحتی یا ناراحتیِ اعضای خانواده می‌شود.','positive',NULL,1,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(18,3,'در بازی یا فعالیت گروهی، معمولاً نوبت و حق دیگران را در نظر می‌گیرد.','positive',NULL,2,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(19,3,'می‌تواند با کودکان مختلف، حتی کودکانی که شباهت زیادی به خودش ندارند، ارتباط برقرار کند.','positive',NULL,3,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(20,3,'وقتی میان دو نفر اختلافی ایجاد می‌شود، می‌تواند درباره راه‌حل یا آشتی کردن صحبت کند.','positive',NULL,4,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(21,3,'در فعالیت گروهی می‌تواند مسئولیتی را که به او سپرده شده انجام دهد.','positive',NULL,5,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(22,3,'اگر کودکی تنها یا ناراحت باشد، گاهی تلاش می‌کند او را وارد بازی یا جمع کند.','positive',NULL,6,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(23,3,'می‌تواند نظر مخالف خود را بدون تحقیر یا مسخره کردن طرف مقابل بیان کند.','positive',NULL,7,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(24,3,'معمولاً می‌تواند تشخیص دهد چه زمانی باید صحبت کند و چه زمانی بهتر است گوش دهد.','positive',NULL,8,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(25,4,'می‌تواند احساس خود را با کلمات بیان کند؛ مثلاً بگوید ناراحت، عصبانی، نگران یا خوشحال است.','positive',NULL,1,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(26,4,'می‌تواند تا حدی توضیح دهد که چرا ناراحت، عصبانی یا خوشحال شده است.','positive',NULL,2,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(27,4,'بعد از اینکه اشتباهی انجام می‌دهد، گاهی خودش درباره رفتار خود فکر می‌کند.','positive',NULL,3,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(28,4,'می‌تواند بعضی از نقاط قوت و ضعف خودش را بیان کند.','positive',NULL,4,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(29,4,'برای انجام بعضی کارهای شخصی خود بدون یادآوری مداوم دیگران برنامه‌ریزی می‌کند.','positive',NULL,5,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(30,4,'وقتی در کاری شکست می‌خورد، بعد از مدتی دوباره برای بهتر انجام دادن آن تلاش می‌کند.','positive',NULL,6,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(31,4,'می‌تواند درباره هدفی که می‌خواهد به آن برسد صحبت کند.','positive',NULL,7,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(32,4,'وقتی متوجه می‌شود رفتار یا تصمیمی از او نتیجه خوبی نداشته، می‌تواند درباره تغییر آن فکر کند.','positive',NULL,8,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(33,5,'از ساختن شکل‌ها و سازه‌ها با لگو یا وسایل مشابه لذت می‌برد.','positive',NULL,1,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(34,5,'در حل پازل‌های متناسب با سن خود، معمولاً توانایی خوبی نشان می‌دهد.','positive',NULL,2,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(35,5,'مسیرها و مکان‌هایی را که قبلاً دیده، نسبتاً خوب به خاطر می‌سپارد.','positive',NULL,3,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(36,5,'در نقاشی، ساختن یا کاردستی به جزئیات ظاهری توجه می‌کند.','positive',NULL,4,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(37,5,'می‌تواند چیزی را که دیده است، با نقاشی، ساختن یا چیدن دوباره بازسازی کند.','positive',NULL,5,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(38,5,'از باز کردن وسایل برای فهمیدن اینکه چگونه ساخته شده‌اند، لذت می‌برد.','positive',NULL,6,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(39,5,'تفاوت میان شکل‌ها، اندازه‌ها و جهت‌های مختلف را نسبتاً سریع تشخیص می‌دهد.','positive',NULL,7,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(40,5,'وقتی موضوعی با تصویر، نقشه یا نمودار نشان داده می‌شود، می‌تواند روابط میان اجزای آن را خوب درک کند.','positive',NULL,8,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(41,6,'در فعالیت‌های ورزشی متناسب با سن خود، هماهنگی بدنی خوبی نشان می‌دهد.','positive',NULL,1,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(42,6,'حرکات جدید را پس از مشاهده دیگران، نسبتاً سریع یاد می‌گیرد.','positive',NULL,2,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(43,6,'در فعالیت‌هایی که نیاز به استفاده دقیق از دست‌ها دارند، عملکرد خوبی نشان می‌دهد.','positive',NULL,3,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(44,6,'از نمایش، نقش‌آفرینی یا اجرای حرکات مربوط به یک داستان لذت می‌برد.','positive',NULL,4,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(45,6,'وقتی خودش یک کار را انجام می‌دهد، معمولاً بهتر از زمانی که فقط درباره آن توضیح می‌شنود یاد می‌گیرد.','positive',NULL,5,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(46,6,'در بازی‌هایی که نیاز به تعادل، هماهنگی یا کنترل بدن دارند، عملکرد خوبی دارد.','positive',NULL,6,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(47,6,'از ساختن، تعمیر کردن یا کار با ابزار و وسایل دستی لذت می‌برد.','positive',NULL,7,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(48,6,'هنگام انجام فعالیت‌های حرکتی، می‌تواند حرکات بدن خود را نسبتاً دقیق کنترل کند.','positive',NULL,8,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(49,7,'درباره حیوانات، گیاهان یا پدیده‌های طبیعی سؤال‌های زیادی می‌پرسد.','positive',NULL,1,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(50,7,'می‌تواند تفاوت میان بعضی حیوانات، گیاهان یا پدیده‌های طبیعی را تشخیص دهد.','positive',NULL,2,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(51,7,'از حضور در محیط‌هایی مانند پارک، باغ، کوه، جنگل یا طبیعت لذت می‌برد.','positive',NULL,3,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(52,7,'به نگهداری از گل، گیاه یا حیوان علاقه و توجه نشان می‌دهد.','positive',NULL,4,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(53,7,'مستندها، کتاب‌ها یا مطالب مربوط به حیوانات و طبیعت را با علاقه دنبال می‌کند.','positive',NULL,5,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(54,7,'نسبت به آسیب زدن به حیوانات، گیاهان یا محیط زیست حساس است.','positive',NULL,6,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(55,7,'در طبیعت به جزئیات کوچک مانند برگ‌ها، حشرات، سنگ‌ها یا تغییرات محیط توجه می‌کند.','positive',NULL,7,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(56,7,'از جمع‌آوری، مقایسه یا بررسی نمونه‌های طبیعی مانند سنگ، برگ یا صدف لذت می‌برد.','positive',NULL,8,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(57,8,'ریتم یک آهنگ یا سرود را نسبتاً درست تشخیص می‌دهد و دنبال می‌کند.','positive',NULL,1,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(58,8,'ریتمی را که می‌شنود، می‌تواند با دست زدن یا ضرب گرفتن تا حد زیادی تکرار کند.','positive',NULL,2,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(59,8,'آهنگ‌ها یا سرودها را نسبتاً سریع به خاطر می‌سپارد.','positive',NULL,3,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(60,8,'تفاوت زیر و بم یا تغییر ارتفاع صدا را متوجه می‌شود.','positive',NULL,4,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(61,8,'هنگام شنیدن موسیقی یا سرود، معمولاً با ریتم آن همراه می‌شود.','positive',NULL,5,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(62,8,'گاهی خودش ریتم، آهنگ یا زمزمه‌ای ایجاد می‌کند.','positive',NULL,6,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(63,8,'تغییر لحن و حالت احساسی صدا، مانند عصبانیت، شادی یا ناراحتی را نسبتاً سریع متوجه می‌شود.','positive',NULL,7,1,'2026-10-18 09:14:17','2026-10-18 09:14:17'),(64,8,'اگر در ریتم یا آهنگ یک سرود یا قطعه آشنا تغییری ایجاد شود، ممکن است متوجه آن شود.','positive',NULL,8,1,'2026-10-18 09:14:17','2026-10-18 09:14:17');
