INSERT INTO `intelligence_observations` VALUES (1,2,10,1,1,NULL,2,NULL,NULL,4,'مستقل',0,'در فعالیت روایتگری کلاسی، داستان را با آغاز، اوج و پایان منسجم تعریف کرد.',NULL,'1404-07-26',2,NULL,'2026-10-18 08:35:09','2026-10-18 08:35:09'),(2,2,10,1,2,NULL,1,NULL,NULL,3,NULL,0,'در خانه اتفاقات مدرسه را با جزئیات کامل و ترتیب زمانی تعریف می‌کند.',NULL,'1404-07-26',2,'مادر','2026-10-18 08:35:09','2026-10-18 08:35:09'),(3,2,10,1,NULL,1,5,NULL,'آرام و باانگیزه',3,'مستقل',0,'در چالش جعبه قصه اسپکتروم، بین هر سه کارت با تسلط و واژگان متنوع ارتباط برقرار کرد.',NULL,'1404-07-26',2,NULL,'2026-10-18 08:35:09','2026-10-18 08:35:09'),(5,2,6,1,34,NULL,2,NULL,NULL,0,'عادی',0,NULL,NULL,'1405-07-26',2,NULL,'2026-10-18 09:32:41','2026-10-18 09:32:45'),(6,2,6,1,33,NULL,2,NULL,NULL,0,'عادی',0,NULL,NULL,'1405-07-26',2,NULL,'2026-10-18 09:33:27','2026-10-18 09:33:27'),(7,2,1,1,1,NULL,1,NULL,NULL,4,NULL,0,NULL,NULL,'1405-07-26',2,'والد','2026-10-18 12:08:01','2026-10-18 12:08:17'),(8,2,1,1,2,NULL,1,NULL,NULL,3,NULL,0,NULL,NULL,'1405-07-26',2,'والد','2026-10-18 12:08:46','2026-10-18 12:08:46'),(9,2,1,1,3,NULL,1,NULL,NULL,1,NULL,0,NULL,NULL,'1405-07-26',2,'والد','2026-10-18 12:08:52','2026-10-18 12:08:52'),(10,2,1,1,4,NULL,1,NULL,NULL,3,NULL,0,NULL,NULL,'1405-07-26',2,'والد','2026-10-18 12:08:56','2026-10-18 12:08:56'),(11,2,1,1,5,NULL,1,NULL,NULL,1,NULL,0,NULL,NULL,'1405-07-26',2,'والد','2026-10-18 12:09:00','2026-10-18 12:09:00'),(12,2,1,1,6,NULL,1,NULL,NULL,4,NULL,0,NULL,NULL,'1405-07-26',2,'والد','2026-10-18 12:09:03','2026-10-18 12:09:03'),(13,2,1,1,7,NULL,1,NULL,NULL,2,NULL,0,NULL,NULL,'1405-07-26',2,'والد','2026-10-18 12:09:17','2026-10-18 12:09:17'),(14,2,1,1,8,NULL,1,NULL,NULL,3,NULL,0,NULL,NULL,'1405-07-26',2,'والد','2026-10-18 12:09:20','2026-10-18 12:09:20'),(15,2,1,1,9,NULL,1,NULL,NULL,2,NULL,0,NULL,NULL,'1405-07-26',2,'والد','2026-10-18 12:34:30','2026-10-18 12:34:30'),(16,2,1,1,10,NULL,1,NULL,NULL,3,NULL,0,NULL,NULL,'1405-07-26',2,'والد','2026-10-18 12:34:33','2026-10-18 12:34:33'