INSERT INTO `mi_config_legacy` VALUES (1,'هوش کلامی 🗣️','افراد با هوش کلامی بالا، مجریان و سخنوران توانمندی هستند.','پرگو و وراجی (تمایل زیاد به صحبت کردن),استفاده از واژگان غنی (دایره لغات وسیع و حاضرجوابی),شنوندگان فعال (دقت به صحبت‌های دیگران),تکلم زودهنگام در کودکی,تعامل کلامی با بزرگسالان در کودکی,صحبت با جزئیات (توضیحات و روایت‌های مفصل),صدای جذاب و رسا (لحن دلنشین و گیرا),تمایل به آموزش در کلاس',''),(2,'هوش منطقی-ریاضی 🔢','افراد با هوش منطقی-ریاضی اغلب مدرسین خود را به چالش می‌کشند.','پرسش‌های مکرر و غیرمعمول (سوالات چالش‌برانگیز),توانایی در دسته‌بندی اطلاعات,یادگیری سریع رنگ‌ها و اسامی,صحبت فراتر از سن (گفتار پخته),توانایی در فهم ریاضیات,علاقه‌مندی به بازی‌های فکری و حل مسئله,علاقه زیاد به یادگیری,تمرکز بالا و تحرک کمتر,نگاه انتقادی به مسائل',''),(3,'هوش بین فردی 🤝','توانایی درک و تعامل مؤثر با دیگران.','درک سریع احساسات اطرافیان,برقراری ارتباط سریع از کودکی,واکنش‌های هیجانی سنجیده و مناسب,موفقیت در بیان عقاید و احساسات,مسالمت‌جو و صلح‌جو در میان همسالان,سازش‌پذیری و معاشرت بالا,دوستان زیاد و توانایی رهبری گروه,درک بالای شرایط و احوال دیگران',''),(4,'هوش درون فردی 🧘','توانایی شناخت خود و کنترل هیجانات درونی.','آرامش و وقار (متانت خاص),ترجیح تنهایی برای حل مسائل,شهود و حس ششم قوی,اعتماد به نفس بالا,توانایی بالا در کنترل احساسات (خشم),اصلاح رفتار پس از اشتباه,لذت از فعالیت‌های فردی (مطالعه و نوشتن),خلاقیت و تخیل بسیار قوی,طرح پرسش‌های وجودی و عمیق,رفتار و پوشش فراتر از سن',''),(5,'هوش تصویری/فضایی 🎨','توانایی تجسم اجسام و خلق آثار بصری.','مهارت بالا در نقاشی,علاقه به مونتاژ و دمونتاژ اسباب‌بازی,توانایی عالی در حل پازل,استعداد در ساخت سازه‌های لگو,موفقیت در فعالیت‌های دستی (مجسمه‌سازی),عملکرد خوب در درس املا,حافظه تصویری قوی,علاقه به اسباب‌بازی‌های هندسی,توانایی در حل مکعب روبیک',''),(6,'هوش جنبشی-حرکتی ⚽','توانایی استفاده از مهارت‌های بدنی و حرکتی.','تحرک زیاد نسبت به همسالان,حرکات تکراری دست و پا هنگام نشستن,ترجیح بازی‌های حرکتی به بازی‌های فکری,مستعد و توانمند در ورزش,داوطلب شدن برای کمک به دیگران,بی‌علاقگی به نشستن طولانی‌مدت,واکنش‌های سریع و ناگهانی,تشخیص بیش‌فعالی (احتمالی),به چالش کشیدن تعادل بدن',''),(7,'هوش طبیعت‌گرا 🌿','علاقه به شناخت و حفظ محیط زیست و موجودات زنده.','علاقه زیاد به گیاهان و حیوانات (نگهداری در منزل),علاقه‌مند به مباحث حیات وحش و طبیعت,علاقه به حضور در طبیعت و فضاهای سرسبز,علاقه به جمع‌آوری نمونه‌های طبیعت (حشرات),حساسیت به حفظ طبیعت و نظافت محیط',''),(8,'هوش موسیقیایی 🎵','حساسیت به ریتم، آهنگ و صداها.','تشخیص ریتم,زمزمه,آواز خواندن,درک تن صدا','بی‌توجهی به صداها');
/*!40000 ALTER TABLE `mi_config_legacy` ENABLE KEYS */;
UNLOCK TABLES;

