INSERT INTO `notes` VALUES (1,'1404/11/01','علی موقع بازی دوتا برج ساخت\n\nعلی با دستش سینه پیرزم رو نشون داد امیر علی گفت ععع بی‌تربیت\n\nعلی رک حرفشو میزنه( بهم برخورد از دختر گفتین تو داستان۰)\n\n\nاشاره نشدن به پیرزن تو داستان ها\n\n---------------------------\n\nعلی ریسک پذیر نیست\nبعد باختش عذرخواهی کرد\n\n---------------------------\n\n\nسجاد میترسه ک تیم بخاطر اون بیاره\n\nعلی زود از بازی ناامید میشه\n\n---------------------------\n\n\nبازی علی خوبه بخاطر ژنتیکش بازی تو خونه با بابا و داداشاش\n\nمحمد مهدی خیلی قانونمنده\nموقع بازی عماد خطا کرد ولی مهمد محنی بهش گفت که نکن و درست بده','2026-04-29 12:50:05',2),(2,'1404/11/29','نکات و نقد هایی که بچه ها از جشن کردن\n\n\nپرهام نظری نداشت\nورود افراد غیره به اشپزخونه \n\nعلی خونه کوچیک بود \nلوکیشنش بد و خطرناک بود \nدور سیستم صوت پر بود و دخالت می‌کردن تو کار علی \nهماهنگی مجری با مسئول سیستم صوت برای پخش سرود \nو هماهنگی بازی\nنبود سراه برق و روشن نشدن ریسه هایی ک علی زده بود\nمجری همون اول جایزه هارو نداد \nمجری باید عوض بشه چون جایزه به همه داده بود😂😂🤦‍♂\n\nمحمدصالح\nپذیرایی دم در باید زودتر اماده میشد \nپیتزا زود دادیم و سرد شده بود\n\nمهدیار ش\nچسب نواری سفت نبود برای همین میریختن بادکنکا\n\nمحمدمهدی \nچسب بادکنک کم بود \nبادکنک ها که میوفتاد بچه ها فکر میکردن جایزه بدیه و انتخاب نمیکردن \nبچه ها جایزه زیاد گرفتن هرکی یکی میگرفت\n\nسجاد\nماشین هایی که تو پارکینگ بودن جا رو کوچیک کرده بودن بیرون بودن بهتر میشد\nبادکنکا کاشکی یک سمت بود \nهرکی که بازی میکرد جایزه میگرفت \n\n\nمهدیار خ \nدیر بهشون گفتیم که کیک ها و اب میوه ها برن بیرون باید زودتر بهشون میگفتیم\n\nامیرعلی \nبعضی بچه ها همش حواسشون به مهمونای خودشون بودن و به جشن فکر نمی‌کردن\nدیوار سنگی بود برای تزئینات\nنمایش نداشتیم','2026-04-29 12:50:05',2),(3,'۱۴۰۵/۰۳/۰۶','نکته نماز \nاداب نماز عطر زدن قبل از نماز که مستحب هست','2026-05-28 07:07:23',2),(4,'۱۴۰۵/۰۴/۱۷','امیرعلی صمدی به قانع منش گفته میخوام از این به بعد شوخی کمتر بکنم تا از امتیازام کم نشه (اروم تر شده بود کلا تو جلسه نسبت به قدیم)\n\nاشتباه چیدمان سین و این نکته که گل کار محتوای اصلی اخر جلسه بود و بچه ها گوش نمیدادن\n\n۲۵ دقیقه تاخیر در خروج از جلسه \n','2026-07-09 08:37:15',2),(5,'۱۴۰۵/۰۶/۰۴','پس زدن دست مسعود توسط علی موقع یاد حضرت که دوستای جلسه بهترینن و باید هوای همو داشته باشیم\n\n\n\nخندیدن عمدی و زیاد علی نسبت به اعضای تیمی ک ساخته شده(استارتش با محمدصالح بود) و همچنین خندیدن عمدی به عماد(فک کنم میخواد عمادم بیاره تو گروهشون)\n\n\n\nتو یک تیم قرار نگرفتن علی و امیرمهدی تا اطلاع ثانوی تحت هیچ شرایطی\n\n\n\nفرادا نماز خوندن امیرمهدی برای اینک زودتر نمازش تموم بشه علیو بخندونه\n\n\n\nمطیع شدن امیرمهدی نسبت به علی و رهبر شدن علی به صورت علنی','2026-08-26 22:12:32',2);
/*!40000 ALTER TABLE `notes` ENABLE KEYS */;
UNLOCK TABLES;

