INSERT INTO `plans` VALUES ('1767381788525','1404/09/19','جلسه شیشم میزبان محمدصالح','low','[{\"type\":\"game\",\"name\":\"بادکمبت\",\"desc\":\"\",\"items\":[{\"name\":\"بادکنک\",\"type\":\"buy\"}]},{\"type\":\"story\",\"name\":\"داستان همنشین حضرت موسی \",\"desc\":\"\",\"items\":[{\"name\":\"کلاه گیس\",\"type\":\"have\"},{\"name\":\"نامه اول جزیره\",\"type\":\"buy\"},{\"name\":\"چتر\",\"type\":\"have\"},{\"name\":\"عینک افتابی\",\"type\":\"have\"}]},{\"type\":\"other\",\"name\":\"هدیه روز مادر طرح فلش \",\"desc\":\"فلش های که به فلش بعدی اشاره دارن تا مادر با دنبال کردنشون برسه به دل نوشته بچه ها\",\"items\":[{\"name\":\"پرینت کاغذ ها\",\"type\":\"buy\"}]}]','۱۸:۳۰ تا ۱۸:۴۵ آنچه گذشت\n\n ۱۸:۴۵ تا ۱۹:۲۰ بازی \nبادکمبت\n\n۱۹:۲۵ تا ۱۹:۴۵ پذیرایی و داستان\nهمنشین حضرت موسی\n\n ۱۹:۴۵ تا ۲۰:۳۰ ساخت کاردستی و هدیه روز مادر','Active','2026-07-09 07:43:50',2),('1767382153858','1404/09/26','جلسه هفتم میزبان عماد','low','[{\"type\":\"game\",\"name\":\"قل بال \",\"desc\":\"\",\"items\":[{\"name\":\"توپ پینگ پنگ\",\"type\":\"have\"},{\"name\":\"لیوان\",\"type\":\"have\"},{\"name\":\"چسب\",\"type\":\"have\"}]},{\"type\":\"story\",\"name\":\"جهانگرد و جزیره پازونگا\",\"desc\":\"\",\"items\":[{\"name\":\"کلاه گیس\",\"type\":\"buy\"},{\"name\":\"چتر\",\"type\":\"buy\"},{\"name\":\"چتر\",\"type\":\"have\"}]},{\"type\":\"yade_hazrat\",\"name\":\"یاد حضرت جهانگرد و جزیره پازونگا\",\"desc\":\"\",\"items\":[]}]','18:30 تا 18:50 \nمرور سریع قوانین ، سوال درباره اتفاقی که بعد از اینکه هدیه رو دادن به اولیا ری اکشن چی بوده \n\n18:50 تا 19:30 \nداستان جهانگرد و یاد حضرتش\n\n19:30 تا 19:45 پذیرایی \n\n19:45 تا 20:30 \nبازی قل بال','Active','2026-07-09 07:43:50',2),('1767382851613','1404/10/03','جلسه هشتم میزبان علی مجردی','low','[{\"type\":\"game\",\"name\":\"تیر و سپر \",\"desc\":\"\",\"items\":[{\"name\":\"زوبین\",\"type\":\"have\"},{\"name\":\"لیوان\",\"type\":\"have\"},{\"name\":\"توپ\",\"type\":\"have\"}]},{\"type\":\"yade_hazrat\",\"name\":\"یاد حضرت بازی سپر \",\"desc\":\"\",\"items\"