DROP TABLE IF EXISTS `practical_activities`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `practical_activities` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `domain_id` int(10) unsigned NOT NULL,
  `title` varchar(255) NOT NULL,
  `instructions` text NOT NULL,
  `age_group` varchar(50) DEFAULT NULL,
  `tools_needed` text DEFAULT NULL,
  `time_needed` varchar(50) DEFAULT NULL,
  `rubric_criteria` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`rubric_criteria`)),
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_act_domain` (`domain_id`,`is_active`),
  CONSTRAINT `practical_activities_ibfk_1` FOREIGN KEY (`domain_id`) REFERENCES `intelligence_domains` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
