LOCK TABLES `practical_activities` WRITE;
/*!40000 ALTER TABLE `practical_activities` DISABLE KEYS */;
INSERT INTO `practical_activities` VALUES (1,1,'چالش جعبه قصه (Project Spectrum Storyboard)','سه کارت تصویری با موضوعات ظاهراً نامربوط در اختیار متربی قرار می‌گیرد. از او خواسته می‌شود یک داستان کوتاه با شروع، اوج و پایان منسجم با پیوند این ۳ کارت تعریف کند.','۷ تا ۱۲ سال','سه کارت تصویری رنگی','۱۰ دقیقه','{\"level_3\":\"روایت منسجم و پرجزئیات با اتصال خلاقانه ۳ کارت و تغییر مناسب تن صدا\",\"level_2\":\"روایت ساده و پیوند حداقلی بین کارت‌ها با نیاز به یک یادآوری کوتاه\",\"level_1\":\"نام بردن مجزا از کارت‌ها بدون ایجاد پیوند روایی پیوسته\"}',1,'2026-10-18 08:29:53'),(2,2,'چالش کشف و گسترش الگو (Pattern Quest)','مربی توالی منظمی از مهره‌ها یا اشکال رنگی را می‌چیند. از متربی خواسته می‌شود قاعده پنهان را کشف کرده و تا ۳ گام بعدی آن را ادامه دهد.','۷ تا ۱۲ سال','مهره‌ها یا کارت‌های هندسی رنگی','۱۰ دقیقه','{\"level_3\":\"کشف سریع قاعده تناوب و تکمیل بی‌نقص الگو بدون خطا\",\"level_2\":\"کشف الگو پس از راهنمایی کوتاه یا آزمون و خطای خوداصلاح‌گر\",\"level_1\":\"عدم تشخیص توالی و چیدمان تصادفی مهره‌ها\"}',1,'2026-10-18 08:29:53'),(3,5,'چالش بازسازی سازه فضایی (Spatial Builder)','متربی تصویر دوبعدی از یک سازه مکعبی با زاویه دید پرسپکتیو را می‌بیند و با استفاده از قطعات لگو یا مکعب‌های چوبی، ماکت سه‌بعدی متناظر را می‌سازد.','۷ تا ۱۲ سال','۸ تا ۱۲ مکعب چوبی یا لگو + کارت راهنما','۱۵ دقیقه','{\"level_3\":\"تطابق کامل ساختار سه‌بعدی، تعداد طبقات و تقارن با تصویر راهنما\",\"level_2\":\"ساخت کلیات سازه با اختلاف جزئی در یک لایه یا زاویه\",\"level_1\":\"دشواری در درک عمق و عدم انطباق با شکل دوبعدی\"}',1,'2026-10-18 08:29:53'),(4,6,'مسیر موانع و تعادل حرکتی (Spectrum Movement Challenge)','اجرای زنجیره حرکتی شامل راه رفتن روی نوار تعادل، پرش جفت‌پا از ۳ مانع نرم کوتاه و انداختن توپ درون سبد از فاصله ۲ متری.','۷ تا ۱۲ سال','نوار تعادل، ۳ مانع نرم، توپ تنیس و سبد','۱۰ دقیقه','{\"level_3\":\"حفظ کامل تعادل، فرود نرم و هماهنگی بالا در پرتاب\",\"level_2\":\"اجرای مسیر با اندکی تزلزل یا نیاز به تکرار مجدد پرتاب\",\"level_1\":\"اشکال در هماهنگی دست و پا یا انصراف از برخی موانع\"}',1,'2026-10-18 08:29:53'),(5,8,'چالش بازتولید ریتم و ملودی (Rhythm Echo)','مربی با دست زدن یا کوبه چوبی یک الگوی ۴ ضربی با کشش‌های متفاوت می‌نوازد. متربی باید بعد از شنیدن، ریتم را عینا بازتولید کند.','۷ تا ۱۲ سال','چوبک ریتم یا کف زدن','۸ دقیقه','{\"level_3\":\"بازتولید دقیق، بی‌درنگ و ریتمیک الگو با تمپوی یکدست\",\"level_2\":\"تکرار ریتم با یک اشتباه کوچک در ضرب‌های فرعی\",\"level_1\":\"کف زدن نامنظم بدون توجه به فواصل ضربه‌ها\"}',1,'2026-10-18 08:29:53'),(6,3,'چالش مأموریت تیمی دونفره (Cooperative Puzzle)','دو متربی باید با هم یک پازل ۲۰ تکه را کامل کنند، به گونه‌ای که یکی فقط راهنمایی کلامی می‌دهد و دیگری قطعات را برمی‌دارد و می‌چیند.','۷ تا ۱۲ سال','پازل ۲۰ تکه','۱۵ دقیقه','{\"level_3\":\"گفتگوی محترمانه، راهنمایی شفاف، صبوری و تشویق هم‌تیمی\",\"level_2\":\"مشارکت موثر با اندکی تمایل به تک‌روی یا تذکر مربی\",\"level_1\":\"قطع همکاری، پرخاش کلامی یا اصرار بر دخالت مستقیم در کار دیگری\"}',1,'2026-10-18 08:29:53'),(7,4,'چالش کارآگاه احساسات و بازتاب درونی (Emotion Detective)','ارائه یک موقعیت چالشی (مثلاً باخت در بازی) و پرسش: «اگر در این شرایط بودی چه حسی داشتی؟ دلیلش چیست و چطور حالت را بهتر می‌کردی؟»','۷ تا ۱۲ سال','کارت سناریوی احساسی','۱۰ دقیقه','{\"level_3\":\"نام‌گذاری دقیق هیجان، تبیین دلیل و ارائه راهکار واقع‌بینانه خودتنظیمی\",\"level_2\":\"تشخیص حس کلی (خوب\\/بد) با بیان دلیل مختصر\",\"level_1\":\"پاسخ نامشخص («نمی‌دانم») و ناتوانی در توصیف حس درونی\"}',1,'2026-10-18 08:29:53'),(8,7,'چالش طبقه‌بندی هوشمند طبیعت (Nature Sorting)','ارائه ۱۰ نمونه یا کارت طبیعی (برگ‌ها، دانه‌ها، سنگ‌ها) به متربی جهت دسته‌بندی بر مبنای یک ویژگی خودیافته و توضیح علت آن.','۷ تا ۱۲ سال','۱۰ نمونه یا کارت طبیعی','۱۲ دقیقه','{\"level_3\":\"دسته‌بندی نظام‌مند بر اساس ویژگی‌های علمی ملموس و تبیین دقیق تفاوت‌ها\",\"level_2\":\"دسته‌بندی بر مبنای یک شاخص ساده ظاهری (مثل اندازه یا رنگ)\",\"level_1\":\"چیدمان تصادفی و ناتوانی در توضیح منطق گروه‌بندی\"}',1,'2026-10-18 08:29:53');
/*!40000 ALTER TABLE `practical_activities` ENABLE KEYS */;
